import React from 'react';

import { _sanitizeSymbol as sanitizeSymbol } from '../../../../../core/utils/sanitize-symbol.js';
import { WithId } from '../../../types/with-id.js';
import { MarkerSymbolWrapper } from '../../annotations-atoms/components/MarkerSymbolWrapper.js';
import { MULTIPLE_EVENTS_CONTENT } from '../constants.js';
import { AnnotationData } from '../types/annotations.js';

export const defineMarkerContent = (data: WithId<AnnotationData>[]) => {
  let markerContent: React.ReactNode;

  if (data.length >= 10) {
    markerContent = MULTIPLE_EVENTS_CONTENT;
  } else if (data.length > 1) {
    markerContent = data.length;
  } else {
    const symbol = data[0].symbol;
    if (symbol) {
      if (typeof symbol === 'string') {
        markerContent = sanitizeSymbol(symbol);
      } else {
        markerContent = <MarkerSymbolWrapper>{symbol}</MarkerSymbolWrapper>;
      }
    }
  }

  return markerContent;
};
